use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        let n: int = parts.len() as int
        if n == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" && n >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(parts[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(parts[1], amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && n >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else {
                let bal: int = acc.get(parts[1]).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(parts[1], bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(parts[1], bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && n >= 4 {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else if !acc.contains_key(parts[2]) {
                println("error: unknown account ${parts[2]}")
            } else if parts[1] == parts[2] {
                println("error: same account")
            } else {
                let a: int = acc.get(parts[1]).unwrap_or(0)
                let b: int = acc.get(parts[2]).unwrap_or(0)
                if a < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(parts[1], a - amt)
                    acc.insert(parts[2], b + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && n >= 2 {
            if !acc.contains_key(parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else {
                let bal: int = acc.get(parts[1]).unwrap_or(0)
                println("${bal}")
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() {
        keys.push(k)
    }
    keys.sort()
    for k in keys {
        let v: int = acc.get(k).unwrap_or(0)
        println("${k} ${v}")
    }
}

